#include <cstdint>
#include <string>

bool crashed(std::uint32_t code) { return (code & 0xC0000000u) == 0xC0000000u; }

std::string describeExit(std::uint32_t code)
{
    switch (code)
    {
    case 0: return "success";
    case 259: return "still running";
    case 0xC0000005u: return "crashed: access violation";
    case 0xC00000FDu: return "crashed: stack overflow";
    case 0xC0000409u: return "crashed: stack buffer overrun or fail-fast";
    case 0xC0000374u: return "crashed: heap corruption";
    case 0xC000013Au: return "stopped with Ctrl+C";
    case 0xE06D7363u: return "unhandled C++ exception";
    default: break;
    }
    if (crashed(code))
    {
        static const char* const HEX{ "0123456789ABCDEF" };
        std::string text{ "crashed: 0x" };
        for (int i{ 7 }; i >= 0; --i) text += HEX[(code >> (4 * i)) & 0xF];
        return text;
    }
    return "failed with code " + std::to_string(code);
}

unitTests:
TEST("crash codes") {
    CHECK(crashed(0xC0000005u));
    CHECK(crashed(0xC0000001u));
    CHECK(!crashed(0));
    CHECK(!crashed(1));
    CHECK(!crashed(0x80000003u));
    CHECK(crashed(0xE06D7363u));
}
TEST("descriptions") {
    CHECK_EQ(describeExit(0), std::string("success"));
    CHECK_EQ(describeExit(259), std::string("still running"));
    CHECK_EQ(describeExit(0xC0000005u), std::string("crashed: access violation"));
    CHECK_EQ(describeExit(0xC00000FDu), std::string("crashed: stack overflow"));
    CHECK_EQ(describeExit(0xC0000409u), std::string("crashed: stack buffer overrun or fail-fast"));
    CHECK_EQ(describeExit(0xC000013Au), std::string("stopped with Ctrl+C"));
    CHECK_EQ(describeExit(0xC0001234u), std::string("crashed: 0xC0001234"));
    CHECK_EQ(describeExit(0xE06D7363u), std::string("unhandled C++ exception"));
    CHECK_EQ(describeExit(2), std::string("failed with code 2"));
    CHECK_EQ(describeExit(0x80000003u), std::string("failed with code 2147483651"));
}

